function hcFree(rel,why){const p=posOfRel(rel.id);if(!p)return;p.estado='Vacante';p.relId='';p.costo=rel.salario||p.costo;p.moneda=cur(rel);
 const j=rel.jefeId&&posOfRel(rel.jefeId);p.reportaId=j?j.id:(p.reportaId||'');p.creada=p.creada||TODAY;p.vacanteDesde=TODAY;posHist(p,why)}
