function moveCand(id,et){const c=get('candidatos',id);if(!c||!et||c.etapa===et)return;const v=get('vacantes',c.vacanteId);
 if(!can('reclutamiento.candidato.gestionar'))return toast('No tienes permiso para mover candidatos');
 if(!v||v.estado!=='Publicada')return toast('Solo se mueven candidatos de vacantes publicadas');
 if(c.descartado||c.etapa==='Contratado'||!v.etapas.includes(et))return;
 if(et===v.etapas[v.etapas.length-1])return toast('«'+et+'» se alcanza al convertir al candidato en colaborador');
 const a=c.etapa;c.etapa=et;cact(c,'Pasó de «'+a+'» a «'+et+'»');log('Cambio de etapa','Candidato',c.nombre,c.id,a,et);save();toast(c.nombre.split(' ')[0]+' pasó a «'+et+'»');render()}
