  const T2={'Revisión':['Enviar a revisión','Otra persona revisará las condiciones antes de aprobarla.','Enviada a revisión'],'Aprobada':['Aprobar oferta','Con la aprobación, Reclutamiento podrá enviarla al candidato.','Oferta aprobada'],'Enviada':['Enviar oferta al candidato','El envío es simulado: quedará en «Mensajes enviados» y el candidato pasará a la etapa «Oferta».','Enviada al candidato'],'Aceptada':['Registrar aceptación','El candidato pasa a pre-ingreso: se le pedirán datos y documentos antes de su primer día.','El candidato aceptó la oferta']}[s];
