 const row=c=>{const e=estGen(c),v=c.vacanteId&&get('vacantes',c.vacanteId);return `<tr><td><b>${esc(c.internoRelId?(v?v.titulo:''):c.nombre)}</b>${c.internoRelId?'':`<div class="muted">${v?esc(v.titulo):'Sin vacante específica'}</div>`}</td><td class="num">${fd(c.creado)}</td><td>${pill(e[0],e[1])}</td></tr>`};
