 ta_ptEdit:()=>openForm(()=>({title:'Portada del portal',fields:[{k:'titulo',l:'Título',req:1,full:1},{k:'ta_desc',l:'Presentación de la empresa',type:'textarea',req:1,full:1}],submit:o=>{const P=C().portal;P.titulo=o.titulo;P.intro=o.ta_desc;log('Edición','Portal de empleos','Portada','','',o.titulo);toast('Portada actualizada')}}),{titulo:C().portal.titulo,ta_desc:C().portal.intro}),
