function procTable(tipo,list){return `<div class="tw"><table><thead><tr><th>Colaborador</th><th>Plantilla</th><th>${tipo==='onboarding'?'Inicio':'Último día'}</th>${tipo==='offboarding'?'<th>Tipo de salida</th>':''}<th style="min-width:150px">Avance</th><th>Vencidas</th><th>Estado</th></tr></thead><tbody>${list.map(p=>{const r=get('relaciones',p.relId),av=avance(p),nl=nLate(p);return `<tr class="click" data-a="ta_procVer" data-id="${p.id}"><td>${r?whoCell(r):'—'}</td><td>${esc(p.plantillaNombre)}</td><td class="num">${fd(p.inicio)}</td>${tipo==='offboarding'?`<td>${esc(p.tipoSalida||'')}</td>`:''}<td><div class="row" style="flex-wrap:nowrap"><div class="bar" style="flex:1;min-width:70px"><i style="width:${av}%"></i></div><b class="num">${av} %</b></div></td><td>${nl?pill(nl,'crit'):'<span class="muted">—</span>'}</td><td>${pEst(p)}</td></tr>`}).join('')}</tbody></table></div>`}
